-- replay-32.sql
-- 互动巡检 cueType=21 合并提示词更新：JSON 输出 → Markdown + <aifupan-data-block> 标签
-- 与话术质检统一范式（PATCH #13 / 2026-06-05 e4da8ae03）
-- 
-- 必须先于代码部署执行！否则新代码上线后正则提取无标签，summaryJson 全 null，无显式告警。
-- 现网 replay-31.sql 已执行（WHERE NOT EXISTS 保护已生效），需 UPDATE 覆盖旧 JSON 格式行。
-- 幂等条件：WHERE ask_type=21 AND trade_id=1 AND tenant_id=0 AND is_deleted=0
--   tenant_id=0 限定通用行（平台级），防误更新租户私有 cueType=21 行（理论上不存在但兜底）

UPDATE tb_cue_words
SET problem = '\## 任务说明\n\n将多个独立单元（具体数量以本次输入实际为准）的直播互动巡检分析结果进行**纯客观合并统计**，严格保留每个单元的原始判定结论，不得修改任何单条弹幕的判定结果，不得添加任何优化方案、改进建议，仅输出合并后的完整表格和统一的概要总结。\n\n\n\n\## 核心执行规则（必须100%严格执行）\n\n1. **绝对禁止修改任何单条弹幕的原始判定结果**：包括"是否1分钟内回复"、"针对性回复判断依据"、"是否属于有效回复"三列的所有内容，必须与原单元分析结果完全一致\n2. **绝对禁止添加任何优化方案、改进建议、问题分析**，仅输出客观的合并统计结果\n3. 严格按照指定格式输出，不得增减任何列，不得添加表格外的任何无关内容\n4. 有效回复率计算必须精确，保留1位小数\n\n\n\n\## 具体操作步骤\n\n1. **表格合并**\n\n\- 将各单元的所有弹幕数据按**弹幕时间升序**排列\n\n\- 完整复制每一行的所有8列内容：弹幕时间(XX:XX:XX)、用户昵称、弹幕内容(疑问/求助)、主播回复话术、回复时间、是否1分钟内回复、针对性回复判断依据、是否属于有效回复\n\n\- 不得遗漏任何一条需回复的弹幕记录\n\n\n\n2. **数据汇总计算**\n\n\- 总需回复弹幕数=各单元各自需回复弹幕数之和\n\n\- 总有效回复数=各单元各自有效回复数之和\n\n\- 总无效回复数=各单元各自无效回复数之和\n\n\- 整体有效回复率=总有效回复数÷总需回复弹幕数×100%，保留1位小数\n\n\n\n3. **无效回复汇总**\n\n\- 完整复制每个单元中所有无效回复的具体情况（原单元总结中描述的无效回复原因）\n\n\- 按弹幕发送时间顺序排列所有无效回复\n\n\n\n\## 输出格式要求\n\n严格按照以下 **Markdown** 结构输出（与话术质检统一范式），不得增减任何区段，不得在指定区段外添加任何文字、代码块标记、注释或前后缀说明。\n\n\### 区段 1：弹幕明细表格\n\n按弹幕时间升序排列，输出所有需回复弹幕（不得遗漏），列固定 8 列：\n\n| 弹幕时间 (XX:XX:XX) | 用户昵称 | 弹幕内容 (疑问/求助) | 主播回复话术 | 回复时间 | 是否1分钟内回复 | 针对性回复判断依据 | 是否属于有效回复 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| ... | ... | ... | ... | ... | ... | ... | ... |\n\n属于有效回复的最后一列单元格必须保留原有的 `<font color="red">是</font>` 格式。\n\n\### 区段 2：摘要总结段（必须用 `<aifupan-data-block>` 标签包裹）\n\n`<aifupan-data-block>` 标签内**仅放概要总结段（3-5 行）**，不包弹幕明细表格。格式：\n\n```\n<aifupan-data-block>\n本场直播整体互动有效回复率为 <X.X%，保留1位小数，含百分号>，总单元数 <N，整数>，需回复弹幕共 <X 条>，其中有效回复 <X 条>，无效回复 <X 条>。\n\n无效回复明细：\n1. <第 N 单元无效回复描述，一字不差复制原单元>\n2. <...>\n（若某单元无无效回复，标注"第 X 单元无无效回复"）\n</aifupan-data-block>\n```\n\n\## 严格约束\n\n1. **整个回复必须 Markdown 全文**，不得包 \```json\``` 代码块标记，不得在 Markdown 之外添加任何前后缀说明\n2. **`<aifupan-data-block>` 标签必须且仅出现一次**，包裹区段 2 摘要总结段；**不得在区段 1（弹幕表格）内出现该标签**\n3. 区段 2 的有效回复率必须保留 1 位小数（X.X% 含百分号字符串，如 `98.9%`）\n4. 区段 2 的无效回复明细必须**一字不差**地复制原单元分析中的表述，不得修改、简化或补充\n5. 若某单元无无效回复，标注 `第 X 单元无无效回复`\n\n\n\n\## 特殊要求\n\n\- 所有属于有效回复的单元格必须保留原有的`<font color="red">是</font>`格式\n\n\- 无效回复的描述必须**一字不差**地复制原单元分析中的表述，不得修改、简化或补充\n\n\- 若某单元无无效回复，标注"第X单元无无效回复"\n',
    update_date = NOW()
WHERE ask_type = 21
  AND trade_id = 1
  AND tenant_id = 0
  AND is_deleted = 0;
